(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  function $(sel, root) { return (root || document).querySelector(sel); }
  function $all(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }

  function routeFromHash() {
    var h = window.location.hash;
    if (h === '#/active') return 'active';
    if (h === '#/completed') return 'completed';
    return 'all';
  }

  function load() {
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  }

  function save() {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId() {
    var max = todos.reduce(function (m, t) {
      return typeof t.id === 'number' && t.id > m ? t.id : m;
    }, 0);
    return max + 1;
  }

  var todos = load();
  var filter = routeFromHash();

  var todoList = $('.todo-list');
  var newTodo = $('.new-todo');
  var main = $('#main');
  var footer = $('.footer');
  var count = $('.todo-count');
  var clearCompleted = $('.clear-completed');
  var toggleAll = $('#toggle-all');
  var filters = $all('.filters a');

  function matchesFilter(todo) {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  }

  function indexOfLi(li) {
    return Array.prototype.indexOf.call(todoList.children, li);
  }

  function render() {
    todoList.innerHTML = '';
    var active = todos.filter(function (t) { return !t.completed; }).length;
    var completed = todos.length - active;

    todos.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');
      li.style.display = matchesFilter(todo) ? '' : 'none';

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroy = document.createElement('button');
      destroy.className = 'destroy';

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = todo.title;

      li.appendChild(view);
      li.appendChild(edit);
      todoList.appendChild(li);
    });

    var n = active;
    count.innerHTML = '<strong>' + n + '</strong> ' + (n === 1 ? 'item' : 'items') + ' left';

    var has = todos.length > 0;
    main.hidden = !has;
    footer.hidden = !has;
    clearCompleted.hidden = completed === 0;
    toggleAll.checked = has && active === 0;

    filters.forEach(function (a) {
      var href = a.getAttribute('href');
      var isSelected =
        (href === '#/active' && filter === 'active') ||
        (href === '#/completed' && filter === 'completed') ||
        (href === '#/' && filter === 'all');
      if (isSelected) a.classList.add('selected');
      else a.classList.remove('selected');
    });
  }

  function commitEdit(edit) {
    var li = edit.closest('li');
    var idx = indexOfLi(li);
    if (idx < 0) return;
    var title = edit.value.trim();
    if (title === '') {
      todos.splice(idx, 1);
    } else {
      todos[idx].title = title;
    }
    save();
    render();
  }

  // New todo
  newTodo.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      var title = newTodo.value.trim();
      if (title !== '') {
        todos.push({ id: nextId(), title: title, completed: false });
        save();
      }
      newTodo.value = '';
      render();
    }
  });

  // Delegated list interactions
  todoList.addEventListener('change', function (e) {
    var toggle = e.target.closest('.toggle');
    if (toggle) {
      var li = toggle.closest('li');
      var idx = indexOfLi(li);
      todos[idx].completed = toggle.checked;
      save();
      render();
    }
  });

  todoList.addEventListener('click', function (e) {
    var destroy = e.target.closest('.destroy');
    if (destroy) {
      var li = destroy.closest('li');
      var idx = indexOfLi(li);
      todos.splice(idx, 1);
      save();
      render();
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (label) {
      var li = label.closest('li');
      li.classList.add('editing');
      var edit = li.querySelector('.edit');
      edit.focus();
    }
  });

  todoList.addEventListener('keydown', function (e) {
    var edit = e.target.closest('.edit');
    if (!edit) return;
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      commitEdit(edit);
    } else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) {
      var li = edit.closest('li');
      li.classList.remove('editing');
      render();
    }
  });

  todoList.addEventListener('focusout', function (e) {
    var edit = e.target.closest('.edit');
    if (!edit) return;
    var li = edit.closest('li');
    if (!li.isConnected || !li.classList.contains('editing')) return;
    commitEdit(edit);
  });

  // Mark all as complete
  toggleAll.addEventListener('change', function () {
    var allCompleted = toggleAll.checked;
    todos.forEach(function (t) { t.completed = allCompleted; });
    save();
    render();
  });

  // Clear completed
  clearCompleted.addEventListener('click', function () {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  });

  // Routing
  window.addEventListener('hashchange', function () {
    filter = routeFromHash();
    render();
  });

  render();
  newTodo.focus();
})();

