(function () {
  const STORAGE_KEY = 'todos-vanillajs';
  const ENTER_KEY = 13;
  const ESCAPE_KEY = 27;

  const $ = (sel, root) => (root || document).querySelector(sel);
  const $all = (sel, root) => Array.prototype.slice.call((root || document).querySelectorAll(sel));

  const routeFromHash = () => {
    const h = window.location.hash;
    if (h === '#/active') return 'active';
    if (h === '#/completed') return 'completed';
    return 'all';
  };

  const load = () => {
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  };

  const save = () => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  };

  const nextId = () => {
    const max = todos.reduce((m, t) => (typeof t.id === 'number' && t.id > m ? t.id : m), 0);
    return max + 1;
  };

  let todos = load();
  let filter = routeFromHash();

  const todoList = $('.todo-list');
  const newTodo = $('.new-todo');
  const main = $('#main');
  const footer = $('.footer');
  const count = $('.todo-count');
  const clearCompleted = $('.clear-completed');
  const toggleAll = $('#toggle-all');
  const filters = $all('.filters a');

  const matchesFilter = (todo) => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  };

  const indexOfLi = (li) => Array.prototype.indexOf.call(todoList.children, li);

  const render = () => {
    todoList.innerHTML = '';
    const active = todos.filter((t) => !t.completed).length;
    const completed = todos.length - active;

    todos.forEach((todo) => {
      const li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');
      li.style.display = matchesFilter(todo) ? '' : 'none';

      const view = document.createElement('div');
      view.className = 'view';

      const toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = todo.completed;

      const label = document.createElement('label');
      label.textContent = todo.title;

      const destroy = document.createElement('button');
      destroy.className = 'destroy';

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      const edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = todo.title;

      li.appendChild(view);
      li.appendChild(edit);
      todoList.appendChild(li);
    });

    const n = active;
    count.innerHTML = `<strong>${n}</strong> ${n === 1 ? 'item' : 'items'} left`;

    const has = todos.length > 0;
    main.hidden = !has;
    footer.hidden = !has;
    clearCompleted.hidden = completed === 0;
    toggleAll.checked = has && active === 0;

    filters.forEach((a) => {
      const href = a.getAttribute('href');
      const isSelected =
        (href === '#/active' && filter === 'active') ||
        (href === '#/completed' && filter === 'completed') ||
        (href === '#/' && filter === 'all');
      if (isSelected) a.classList.add('selected');
      else a.classList.remove('selected');
    });
  };

  const commitEdit = (edit) => {
    const li = edit.closest('li');
    const idx = indexOfLi(li);
    if (idx < 0) return;
    const title = edit.value.trim();
    if (title === '') {
      todos.splice(idx, 1);
    } else {
      todos[idx].title = title;
    }
    save();
    render();
  };

  // New todo
  newTodo.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      const title = newTodo.value.trim();
      if (title !== '') {
        todos.push({ id: nextId(), title: title, completed: false });
        save();
      }
      newTodo.value = '';
      render();
    }
  });

  // Delegated list interactions
  todoList.addEventListener('change', (e) => {
    const toggle = e.target.closest('.toggle');
    if (toggle) {
      const li = toggle.closest('li');
      const idx = indexOfLi(li);
      todos[idx].completed = toggle.checked;
      save();
      render();
    }
  });

  todoList.addEventListener('click', (e) => {
    const destroy = e.target.closest('.destroy');
    if (destroy) {
      const li = destroy.closest('li');
      const idx = indexOfLi(li);
      todos.splice(idx, 1);
      save();
      render();
    }
  });

  todoList.addEventListener('dblclick', (e) => {
    const label = e.target.closest('label');
    if (label) {
      const li = label.closest('li');
      li.classList.add('editing');
      const edit = li.querySelector('.edit');
      edit.focus();
    }
  });

  todoList.addEventListener('keydown', (e) => {
    const edit = e.target.closest('.edit');
    if (!edit) return;
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      commitEdit(edit);
    } else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) {
      const li = edit.closest('li');
      li.classList.remove('editing');
      render();
    }
  });

  todoList.addEventListener('focusout', (e) => {
    const edit = e.target.closest('.edit');
    if (!edit) return;
    const li = edit.closest('li');
    if (!li.isConnected || !li.classList.contains('editing')) return;
    commitEdit(edit);
  });

  // Mark all as complete
  toggleAll.addEventListener('change', () => {
    const allCompleted = toggleAll.checked;
    todos.forEach((t) => { t.completed = allCompleted; });
    save();
    render();
  });

  // Clear completed
  clearCompleted.addEventListener('click', () => {
    todos = todos.filter((t) => !t.completed);
    save();
    render();
  });

  // Routing
  window.addEventListener('hashchange', () => {
    filter = routeFromHash();
    render();
  });

  render();
  newTodo.focus();
})();

